{
  "name": "opencode-direnv",
  "version": "1.1.1",
  "description": "OpenCode plugin that integrates direnv environment loading into shell commands",
  "type": "module",
  "main": "src/index.ts",
  "exports": {
    ".": {
      "import": "./src/index.ts"
    }
  },
  "files": [
    "src"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "direnv",
    "plugin"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/dan-online/opencode-direnv"
  },
  "scripts": {
    "lint": "oxlint src",
    "lint:fix": "oxlint --fix src",
    "fmt": "oxfmt src",
    "fmt:check": "oxfmt --check src",
    "check": "oxlint src && oxfmt --check src"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@commitlint/cli": "^20.5.0",
    "@commitlint/config-conventional": "^20.5.0",
    "@opencode-ai/plugin": "^1.0.147",
    "oxfmt": "^0.41.0",
    "oxlint": "^1.56.0"
  }
}
